  if (!tokens || typeof tokens !== 'object' || Array.isArray(tokens)) tokens = {};
  let token = tokens[key];
  if (!token) {
    token = randomBytes(24).toString('hex');
    tokens[key] = token;
    saveJsonSync(UNSUBSCRIBE_TOKENS_FILE, tokens);
  }
  const s = site();
  return `${s.alternate}/unsubscribe/${token}`;
