        logAdminAction(emailFromSid(sid) || 'admin', 'matrix_set_role', {
          userId: targetUserId,
          powerLevel: targetPl,
          roomId
        });

        return jsonResp(200, { ok: true, userId: targetUserId, powerLevel: targetPl });
